window.SBL_IGCSE_PPQ = {"topic": "2.1 Government and the Economy", "img": "/igcse/economics/learn/past-papers-img/", "lessons": {"IGEN2101": {"n": 1, "title": "Economic growth and the economic cycle", "href": "/igcse/economics/learn/government-and-the-economy/l01-economic-growth"}, "IGEN2102": {"n": 2, "title": "Low and stable inflation", "href": "/igcse/economics/learn/government-and-the-economy/l02-inflation"}, "IGEN2103": {"n": 3, "title": "Low unemployment", "href": "/igcse/economics/learn/government-and-the-economy/l03-unemployment"}, "IGEN2104": {"n": 4, "title": "The current account of the balance of payments", "href": "/igcse/economics/learn/government-and-the-economy/l04-current-account"}, "IGEN2105": {"n": 5, "title": "Protecting the environment and government controls", "href": "/igcse/economics/learn/government-and-the-economy/l05-protecting-the-environment"}, "IGEN2106": {"n": 6, "title": "Redistribution of income", "href": "/igcse/economics/learn/government-and-the-economy/l06-redistribution-of-income"}, "IGEN2107": {"n": 7, "title": "Fiscal policy", "href": "/igcse/economics/learn/government-and-the-economy/l07-fiscal-policy"}, "IGEN2108": {"n": 8, "title": "Monetary policy", "href": "/igcse/economics/learn/government-and-the-economy/l08-monetary-policy"}, "IGEN2109": {"n": 9, "title": "Supply-side policy", "href": "/igcse/economics/learn/government-and-the-economy/l09-supply-side-policy"}, "IGEN2110": {"n": 10, "title": "Conflicts between objectives and policies", "href": "/igcse/economics/learn/government-and-the-economy/l10-relationships-between-objectives"}}, "parts": [{"key": "2020jan-p2r-1a", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 1, "id": "1(a)", "marks": 1, "text": "What is calculated by using the consumer price index (CPI)?", "intro": "", "options": [["A", "Redistribution of income"], ["B", "Inflation rate"], ["C", "Economic growth"], ["D", "Exchange rate"]], "answer": "B", "type": "mcq", "lesson": "IGEN2102", "ms": "AO1 1 marks\nB Inflation rate (1)\nQuestion Answer Number", "sources": []}, {"key": "2020jan-p2r-1b", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 1, "id": "1(b)", "marks": 1, "text": "The sale or transfer of public sector assets to the private sector is known as", "intro": "", "options": [["A", "monetary policy"], ["B", "public expenditure"], ["C", "privatisation"], ["D", "fiscal policy"]], "answer": "C", "type": "mcq", "lesson": "IGEN2109", "ms": "AO1 1 mark\nC privatisation (1)\nQuestion Answer Number", "sources": []}, {"key": "2020jan-p2r-1c", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 1, "id": "1(c)", "marks": 2, "text": "What is meant by the term boom?", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2101", "ms": "AO1 2 marks\nAward 1 mark for reference to economic cycle and 1 mark for reference to high levels of economic activity/employment\nA phase in the economic cycle (1) with the highest levels of economic activity/with the highest levels of employment (1). (2)\nAccept any other appropriate response. Question Answer Number", "sources": []}, {"key": "2020jan-p2r-1d", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 1, "id": "1(d)", "marks": 2, "text": "What is meant by the term shoe leather costs?", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2102", "ms": "AO1 2 marks\nAward 1 mark for reference to time and effort and 1 mark for reference to purchasing goods The costs to firms and consumers of searching for the lowest prices (1)\nwhen inflation is high/prices are rising rapidly (1).\nAccept any other appropriate response. (2)\nQuestion Answer Number", "sources": []}, {"key": "2020jan-p2r-1h", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 1, "id": "1(h)", "marks": 6, "text": "Analyse how a reduction in direct taxation is likely to affect the standard of living in a country such as Vietnam.", "intro": "Vietnam has progressive income tax rates that range from 5% to 35% depending on income.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2107", "ms": "AO2 (3 marks)/AO3 (3 marks)\n\nAO2 and AO3\n• Direct taxes are government charges imposed on income and wealth\n• Lowering direct taxes such as income tax rates will result in employees keeping more take home pay\n• This increases disposable income from employment and gives an incentive to work rather than live on benefits\n• Increased income could be spent on more/better quality goods and services, thereby increasing standard of living in Vietnam\n• With greater disposable income being spent within the Vietnamese economy, output and employment may increase\n\n0 No rewardable material.\n\nLevel 1 1–2 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n\nLevel 2 3–4 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n\nLevel 3 5–6 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3). Question Answer Number", "sources": []}, {"key": "2020jan-p2r-2c", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 2, "id": "2(c)", "marks": 1, "text": "State one macroeconomic objective.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2101", "ms": "AO1 1 mark\nAward 1 mark for one correct objective.\n• Economic growth\n• Low and stable inflation\n• Low unemployment\n• Surpluses or equilibrium on current account\n• Redistribution of income\n• Protection of the environment\nAccept any other appropriate responses. (1)\nQuestion Answer Number", "sources": []}, {"key": "2020jan-p2r-2e", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 2, "id": "2(e)", "marks": 3, "text": "Explain one reason why the Indian Government’s fiscal deficit is likely to stimulate economic growth.", "intro": "India set a target for its fiscal deficit of 3.3% of its GDP for the year ending March 2019.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2107", "ms": "AO2 3 marks\nAward 1 mark for identifying a relevant reason\nAward 1 mark for developing the reason\nAward 1 mark for the response being in context\n• One reason is that the government can spend more within the economy (1), this overspend can be used to invest in the public services such as infrastructure (1), and this can create jobs within the Indian economy stimulating economic growth (1).\nAccept any other appropriate response. (3)\nQuestion Answer Number", "sources": []}, {"key": "2020jan-p2r-3a", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 3, "id": "3(a)", "marks": 1, "text": "Which one of the following policies is most likely to reduce the rate of inflation?", "intro": "", "options": [["A", "Lower interest rates"], ["B", "Increased money supply"], ["C", "Higher government spending"], ["D", "Higher taxation"]], "answer": "D", "type": "mcq", "lesson": "IGEN2108", "ms": "AO1 1 mark\nD Higher taxation (1)\nQuestion Answer Number", "sources": []}, {"key": "2020jan-p2r-3c", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 3, "id": "3(c)", "marks": 3, "text": "Explain one likely impact of this change in inflation on the current account of the balance of payments for a country such as Egypt.", "intro": "In 2018, the annual rate of inflation in Egypt was 16% in September and 17.7% in October.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2104", "ms": "AO2 3 marks\nAward 1 mark for identifying an impact\nAward 1 mark for developing the impact\nAward 1 mark for the response being in context\n• One impact is a fall in demand for Egyptian exports (1). Inflation of 17.7% makes domestic goods more expensive (1)\nso other countries may not buy Egyptian goods resulting in a deficit on the current account (1).\n• One impact is an increase in imported goods (1). Inflation of 17.7% makes imports appear cheaper than Egyptian goods and services (1) so consumers prefer to purchase imports therefore having a negative impact on the current account (1).\nAccept any other appropriate response. (3)\nNumber", "sources": []}, {"key": "2020jan-p2r-3e", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 3, "id": "3(e)", "marks": 9, "text": "With reference to the data above and your knowledge of economics, assess the likely effectiveness of regulation to protect the environment in a country such as Australia.", "intro": "In Western Australia, single-use plastic bags were banned in July 2018 but fines were not enforced. However, from 2019, under new regulations, any shops providing customers with the banned plastic bags may face prosecution, with fines of up to AUS$5 000. The government is relying on shoppers to report retailers that break the rules.\n\nThe Environment Minister Stephen Dawson said the ban is well supported by the community. He said “Taking plastic bags out of litter is a significant step towards protecting our environment”.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2105", "ms": "AO2 (3 marks)/AO3 (3 marks)/AO4 (3 marks)\n\nAO2 and AO3\n• The use of regulation could be an effective way to reduce usage especially as the fine of AUS$5 000 is very high\n• This could stop retailers issuing plastic bags to customers thereby reducing the chance of plastic bags ending up in litter\n• Most consumers and retailers will want to follow the regulations and will therefore not use plastic bags\n• This is supported by the Environment Minister who states that this is a popular policy with many people\n\nAO4\n• However, banning plastic bags by regulation and issuing fines does not mean its consumption will completely reduce demand\n• The plastic bags have been banned since 2018 but no fines have been given out for using the plastic bags\n• The effectiveness will also depend upon shoppers reporting retailers for giving out plastic bags\n• There needs to effective policing of the ban for it to work properly\n\n0 No rewardable material.\n\nLevel 1 1–3 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n• Only offers one viewpoint, meaning there is an unbalanced and incomplete evaluation, showing limited understanding and awareness (AO4).\n\nLevel 2 4–6 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n• Offers more than one viewpoint but the argument may lack balance, leading to an evaluation that may not demonstrate full understanding and awareness (AO4).\n\nLevel 3 7–9 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3).\n• Offers more than one viewpoint. The argument is well balanced and coherent, leading to an evaluation that demonstrates full understanding and awareness (AO4). Number", "sources": []}, {"key": "2020jan-p2r-4a", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 4, "id": "4(a)", "marks": 2, "text": "Calculate, to two decimal places, the average rate of unemployment in the UK in December 2018. You are advised to show your working.", "intro": "Figure 2 shows the UK’s unemployment rates for 16–64 year olds in different regional areas in December 2018.\n\n(Source: adapted from ons.gov.uk)", "options": [], "answer": null, "type": "write", "lesson": "IGEN2103", "ms": "AO2 2 marks\nAward 1 mark for calculating the average rate of unemployment. (4.8 + 4.6 + 4.3 + 2.9 + 3.0 ) (1)\n5\nAward 1 mark for the correct answer. = 3.92% (1)\nAward 2 marks if the average percentage of 3.92% is accurately calculated with no workings shown\nAward 1 mark if correct answer is shown, i.e. 3.92 but with no (2)\npercentage sign, even if no calculations are shown.\nDo not award marks for the formula. Number", "sources": [{"src": "p2r-2020jan-fig2.png", "figs": [2]}]}, {"key": "2020jan-p2r-4b", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 4, "id": "4(b)", "marks": 6, "text": "With reference to the data in Figure 2 and your knowledge of economics, analyse one possible reason why rates of unemployment vary in the different regional areas of the UK.", "intro": "Figure 2 shows the UK’s unemployment rates for 16–64 year olds in different regional areas in December 2018.\n\n(Source: adapted from ons.gov.uk)", "options": [], "answer": null, "type": "write", "lesson": "IGEN2103", "ms": "AO2 (3 marks)/AO3 (3 marks)\n\nAO2 and AO3\n• Unemployment occurs when people of working age are able and willing to work but cannot find employment\n• The different regional rates could indicate that the UK is suffering from structural unemployment in the different regions\n• The rates of unemployment are highest in places such as the North of England (4.8%) and the Midlands (4.6%)\n• The UK has suffered from a decline in the secondary sector of the economy and has moved more towards tertiary\n• There could be a lack of skills and experience amongst the unemployed making it harder to find employment in certain areas of the UK\n• This therefore has resulted in different rates of unemployment in different parts of the UK\n\n0 No rewardable material.\n\nLevel 1 1–2 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n\nLevel 2 3–4 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n\nLevel 3 5–6 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3). Number", "sources": [{"src": "p2r-2020jan-fig2.png", "figs": [2]}]}, {"key": "2020jan-p2r-4c", "paper": "2020jan-p2r", "paperLabel": "January 2020 · Paper 2R", "q": 4, "id": "4(c)", "marks": 12, "text": "With reference to the data above and your knowledge of economics, evaluate whether an increase in education and training is the most effective way to reduce unemployment for a country such as the UK.", "intro": "A report by accountancy firm PwC said that the UK could boost its GDP by around £40bn a year if it reduces the number of young people who are not in education, employment or training. The UK only ranks 19th out of 35 countries on this latest report, with Germany performing the best in the EU.\n\nJohn Hawksworth, chief economist at PwC UK, comments, “Employers need to work with universities, schools and other educational providers to ensure young people have the skills they need for the age of automation. They also need to help in retraining older workers to adapt to these new technologies”.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2109", "ms": "AO2 (4 marks)/AO3 (4 marks)/AO4 (4 marks)\n\nAO2 and AO3\n• Education and training are examples of supply-side policies designed to improve the productive potential of an economy\n• Investment in education and training can help unemployed workers to acquire new skills so they can gain employment\n• Many unemployed workers lack the necessary skills needed to get a job, especially older workers who may need retraining to gain digital skills\n• This could help to reduce structural unemployment within the UK\n• A better educated and trained workforce could enable the UK to produce more goods and services thus increasing economic growth\n\nAO4\n• However, education and training tend to be long-term and there is a delay in an unemployed worker gaining new skills and being able to enter the labour force\n• There is a financial cost to the UK government of offering education and training to unemployed workers which could be spent on other public services\n• Some of the UK’s unemployment may not be structural and could in fact be due to cyclical unemployment\n• If the main cause of unemployment in the UK is due to other reasons then demand side policies such as fiscal and monetary might be more effective in reducing unemployment\n• If the UK is suffering from a range of different types of unemployment, then a combination of policies would be the most effective\n\n0 No rewardable material.\n\nLevel 1 1–4 • Demonstrates isolated elements of relevant knowledge and understanding; may lack development of relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Chain of reasoning may be attempted. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n• Only offers one viewpoint, meaning there is an unbalanced and incomplete evaluation, showing limited understanding and awareness. A judgement or conclusion is unlikely to be attempted (AO4).\n\nLevel 2 5–8 • Demonstrates partial selectivity and some accurate knowledge and understanding by developing some relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Chain of reasoning will be present but may be limited. Interpretation of economic information will be good, with some analysis of issues (AO3).\n• Offers more than one viewpoint but the argument may lack balance, leading to an evaluation that may not demonstrate full understanding and awareness. A judgement or conclusion is attempted, but may not be fully supported (AO4).\n\nLevel 3 9–12 • Demonstrates specific and accurate knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Chain of reasoning will be coherent and logical. Interpretation of economic information will be excellent with a thorough analysis of issues (AO3).\n• Offers more than one viewpoint. The argument is well balanced and coherent, leading to an evaluation that demonstrates full understanding and awareness. A supported judgement or conclusion is present (AO4).", "sources": []}, {"key": "2021-p2-1a", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 1, "id": "1(a)", "marks": 1, "text": "Which type of unemployment occurs when the demand for a product is only at certain times of the year?", "intro": "", "options": [["A", "Structural"], ["B", "Cyclical"], ["C", "Seasonal"], ["D", "Voluntary"]], "answer": "C", "type": "mcq", "lesson": "IGEN2103", "ms": "AO1 1 mark The only correct answer is:\nC Seasonal\nA is not correct because this is caused by changes in whole industries\nB is not correct because this is caused by falling demand as a result of a downturn in the economic cycle\nD is not correct because this is caused from people choosing not to work (1)\nQuestion Which one of the following terms refers to a tax on imported goods? Number Answer", "sources": []}, {"key": "2021-p2-1c", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 1, "id": "1(c)", "marks": 2, "text": "What is meant by the term recession?", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2101", "ms": "AO1 2 marks\nAward 1 mark for reference to fall in GDP and 1 mark for reference to time period\nA fall in GDP (1) for two successive quarters (1).\nAccept any other appropriate response (2)\nQuestion What is meant by the term dumping? Number Answer", "sources": []}, {"key": "2021-p2-1e", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 1, "id": "1(e)", "marks": 2, "text": "Calculate the fiscal surplus/deficit in Indian rupees crore (Rs) for India in 2019–2020. You are advised to show your working.", "intro": "Figure 1 shows the government revenue and expenditure in rupees crore for India in 2019–2020.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2107", "ms": "A02 2 marks\nAward 1 mark for showing the calculation\n2 080 201 Rs – 2 784 200 Rs (1)\nAward 1 mark for the correct answer = –703 999 Rs (1)\nAward 2 marks for the correct answer of –703 999 Rs even if no calculations are shown.\nAward 1 mark if the answer given is –703 999 with or without calculations shown\nDo not award marks for the formula (2)\nQuestion Using the diagram below, draw the likely effects of the introduction of Number a subsidy on the equilibrium price and quantity of new cars for families with three or more children. Label the new curve, the new Mark equilibrium price and the new equilibrium quantity.", "sources": [{"src": "p2-2021-fig1.png", "figs": [1]}]}, {"key": "2021-p2-1g", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 1, "id": "1(g)", "marks": 3, "text": "Explain one benefit to the UK Government of providing parks.", "intro": "The UK has 13 national parks with the Lake District National Park being the largest and most popular. It had over 19.17 million visitors in 2018. Woodland covers over 12% of the national park.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2105", "ms": "AO2 3 marks\nAward 1 mark for identifying a relevant benefit\nAward 1 mark for developing the benefit\nAward 1 mark for the response being in context\n• One benefit is that national parks can protect a large area of land (1). The Lake District National Park has over 12% of woodland that is protected (1). Restrictions are in place to stop business activities that could damage the environment (1)\n• One benefit is that national parks can be used for recreational purposes (1). Over 19.17 million people visited the Lake District National Park in 2018 (1) increasing tourism for local firms (1)\nAccept any other appropriate response (3)\nQuestion With reference to the data above and your knowledge of economics, analyse Number the benefits of FDI for a country such as Ireland.", "sources": []}, {"key": "2021-p2-2b", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 2, "id": "2(b)", "marks": 1, "text": "Which one of the following is likely to result in poverty?", "intro": "", "options": [["A", "High literacy rates"], ["B", "Low GDP per capita"], ["C", "Low rates of tax"], ["D", "High employment rates"]], "answer": "B", "type": "mcq", "lesson": "IGEN2106", "ms": "AO1 1 mark The only correct answer is:\nB Low GDP per capita\nA is not correct because this can result in people gaining jobs and therefore income\nC is not correct because economic agents would retain more of their income\nD is not correct because more people are in paid employment (1)\nQuestion State one effect on the balance of payments of improved quality of Number foreign goods. Mark", "sources": []}, {"key": "2021-p2-2c", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 2, "id": "2(c)", "marks": 1, "text": "State one effect on the balance of payments of improved quality of foreign goods.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2104", "ms": "AO1 1 mark\nAward 1 mark for one correct effect\n• Higher imports\n• Worsened balance of payments\n• Lower exports\n• Increased deficit\n• Worsened surplus\nAccept any other appropriate response (1)\nQuestion What is meant by the term free trade? Number Answer", "sources": []}, {"key": "2021-p2-2e", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 2, "id": "2(e)", "marks": 3, "text": "Explain one impact of rising unemployment on consumer confidence for a country such as Argentina.", "intro": "In the first quarter of 2019 the unemployment rate in Argentina increased by 1% to 10.1%.\n\nThis was the highest level in 13 years.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2103", "ms": "AO2 3 marks\nAward 1 mark for identifying a relevant impact\nAward 1 mark for developing the impact\nAward 1 mark for the response being context\n• One impact is that consumer confidence is likely to fall (1). High rates of unemployment of 10.1% may make consumers more cautious (1). This can cause lower levels of consumer spending (1)\nAccept any other appropriate response (3)\nQuestion Explain one reason why the reduced cost of communication has Number helped to increase globalisation. Mark", "sources": []}, {"key": "2021-p2-2g", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 2, "id": "2(g)", "marks": 9, "text": "With reference to the data above and your knowledge of economics, assess the use of taxation to protect the environment in a country such as Germany.", "intro": "In 2019, Germany was considering increasing the tax on meat to protect the environment and improve animal welfare. Currently meat in Germany has a reduced tax rate of 7%.\n\nSome political groups are arguing that this should increase to the standard 19%. According to United Nations research, methane from animals accounts for 14.5% of greenhouse gas emissions – more than the direct emissions from transport.\n\n(Source: adapted from independent.co.uk)", "options": [], "answer": null, "type": "write", "lesson": "IGEN2105", "ms": "AO2 (3 marks)/AO3 (3 marks)/AO4 (3 marks)\n\nAO2 and AO3\n• Taxation can be imposed on activities that damage the environment\n• Taxation is used to ensure consumers and producers pay the full social cost of producing a good or service\n• Increasing taxation from 7% to 19% would substantially increase the price of meat for consumers which may result in less demand for meat products\n• This would reduce the amount of greenhouse gas emissions caused by animals\n• Increased taxation could also raise additional revenue for the German Government\n• This could be used to finance other pollution reduction schemes or improve animal welfare\n• Taxation provides a market incentive for firms and consumers to switch to meat alternatives which may not cause as much environmental damage\n\nAO4\n• However, increasing taxes on meat may reduce incomes for farmers if demand falls for meat products\n• Increasing taxes on meat products may reduce the choice for consumers of what food they can afford, particularly low-income families\n• Demand for meat may be quite inelastic and an increase in tax may do little to reduce demand and therefore only marginally reduce the amount of pollution\n• There are other methods that might be more effective in protecting the environment, such as subsidies, fines or pollution permits\n• The German Government should use a combination of methods to protect the environment\n\n0 No rewardable material.\n\nLevel 1 1–3 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n• Only offers one viewpoint, meaning there is an unbalanced and incomplete evaluation, showing limited understanding and awareness (AO4).\n\nLevel 2 4–6 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n• Offers more than one viewpoint but the argument may lack balance, leading to an evaluation that may not demonstrate full understanding and awareness (AO4).\n\nLevel 3 7–9 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3).\n• Offers more than one viewpoint. The argument is well balanced and coherent, leading to an evaluation that demonstrates full understanding and awareness (AO4). Question What is the total amount of revenue raised by indirect taxes? Number Answer", "sources": []}, {"key": "2021-p2-3a", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 3, "id": "3(a)", "marks": 1, "text": "What is the total amount of revenue raised by indirect taxes?", "intro": "Figure 3 shows selected UK Government receipts from taxation in 2019.", "options": [["A", "£454.6bn"], ["B", "£321.7bn"], ["C", "£218.2bn"], ["D", "£85.3bn"]], "answer": "C", "type": "mcq", "lesson": "IGEN2107", "ms": "AO2 1 mark The only correct answer is:\nC £218.2bn\nA is not correct because this is calculated by Sales tax (VAT) + Income tax\nB is not correct because this figure is calculated by Income tax + Tariffs\nD is not correct because this is calculated by Tariffs + Business tax (1)\nQuestion Member countries of a trading bloc agree to Number Answer", "sources": [{"src": "p2-2021-fig3.png", "figs": [3]}]}, {"key": "2021-p2-3d", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 3, "id": "3(d)", "marks": 6, "text": "With reference to the data above and your knowledge of economics, analyse why the Slovenian Government might want to increase investment in healthcare.", "intro": "The Slovenian Government spent €3.05bn on healthcare in 2019. This included additional funding for reducing the time people were waiting for treatment and an extra €104m to cover the recent increase in wage rates for healthcare staff.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2106", "ms": "AO2 (3 marks)/AO3 (3 marks)\n\nAO2 and AO3\n• Healthcare provides medicines and medical treatments to increase the overall health of the nation\n• The social benefit of providing healthcare to an individual often exceeds the private benefit through immunisation programmes\n• Investing €3.05bn in healthcare means that illnesses can be treated quickly therefore improving life expectancy across all age groups in Slovenian\n• This can help to reduce inequality and poverty by enabling the population to work and gain income from being fit and healthy\n• Having a healthier workforce reduces the amount of sickness absence and potentially improves labour productivity\n• This could result in economic growth and therefore help to improve standards of living in Slovenia\n• Healthcare also provides many jobs for healthcare workers including nurses and doctors which helps to reduce unemployment\n\n0 No rewardable material.\n\nLevel 1 1–2 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n\nLevel 2 3–4 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n\nLevel 3 5–6 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3). Question With reference to the data above and your knowledge of economics, assess the Number likely benefits of economic growth for a country such as Turkmenistan.", "sources": []}, {"key": "2021-p2-3e", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 3, "id": "3(e)", "marks": 9, "text": "With reference to the data above and your knowledge of economics, assess the likely benefits of economic growth for a country such as Turkmenistan.", "intro": "In recent years Turkmenistan has been one of the fastest growing economies. The most important sector of the economy is oil and natural gas extraction, which accounts for more than 60% of GDP. Although agriculture accounts for only 10% of GDP, it employs 50% of the labour force. Turkmenistan has seen annual GDP growth rates of 6.2%.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2101", "ms": "AO2 (3 marks)/AO3 (3 marks)/AO4 (3 marks)\n\nAO2 and AO3\n• Economic growth is the increase in the level of output by a nation and is one of the main macroeconomic objectives\n• Turkmenistan has seen a 6.2% GDP growth rate which could result in an increase in employment levels in the oil and natural gas extraction industries\n• This is due to firms requiring more workers for production as the economy grows\n• Figure 4 shows an increase over time of GDP per capita which indicates that people have more income in Turkmenistan\n• Consumers might be able to purchase more goods and services thereby improving standards of living\n• Rapid economic growth could also help to reduce poverty in Turkmenistan particularly as over 50% of the labour force work in agriculture\n\nAO4\n• However, not all economic growth is good for an economy\n• If economic growth is too fast, the Turkmenistan economy may overheat\n• This could result in demand pull and cost push inflation\n• Economic growth could also result in more negative externalities such as pollution and waste\n• Turkmenistan relies heavily on the extraction of finite resources such as oil and gas which may cause a long-run depletion of natural resources\n• Rapid increases in GDP can lead to a higher level of inequality as the gains from growth may go to only a few people\n\n0 No rewardable material.\n\nLevel 1 1–3 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n• Only offers one viewpoint, meaning there is an unbalanced and incomplete evaluation, showing limited understanding and awareness (AO4).\n\nLevel 2 4–6 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n• Offers more than one viewpoint but the argument may lack balance, leading to an evaluation that may not demonstrate full understanding and awareness (AO4).\n\nLevel 3 7–9 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3).\n• Offers more than one viewpoint. The argument is well balanced and coherent, leading to an evaluation that demonstrates full understanding and awareness (AO4). Question Calculate how much interest, in Yuan (¥), Zhang Li received in one Number year. You are advised to show your working. Mark", "sources": [{"src": "p2-2021-fig4.png", "figs": [4]}]}, {"key": "2021-p2-4a", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 4, "id": "4(a)", "marks": 2, "text": "Calculate how much interest, in Yuan (¥), Zhang Li received in one year. You are advised to show your working.", "intro": "Zhang Li had 8 000 Yuan (¥) in her savings account. The annual interest rate for this savings account was 2.25%.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2108", "ms": "AO2 2 marks\nAward 2 marks for calculating the interest on savings (¥8 000 ÷ 100) × 2.25 (1) = ¥180 (1)\nAward 2 marks for the correct answer of ¥180 is accurately calculated with no workings shown\nAward 1 mark if the answer given is 180 with or without calculations shown\nDo not award marks for the formula (2)\nQuestion With reference to the data above and your knowledge of economics, Number analyse the impact of inflation on individuals in a country such as China.", "sources": []}, {"key": "2021-p2-4b", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 4, "id": "4(b)", "marks": 6, "text": "With reference to the data above and your knowledge of economics, analyse the impact of inflation on individuals in a country such as China.", "intro": "In July 2019, China’s annual inflation rate increased to 2.8%. This was the highest rate since February 2018.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2102", "ms": "AO2 (3 marks)/AO3 (3 marks)\n\nAO2 and AO3\n• Inflation is the rate at which the general level of prices for goods and services is rising within an economy\n• The current inflation rate is 2.8%, an increase on the previous month, which reduces the purchasing power of consumers if wages do not keep up with inflation\n• This may make goods and services too expensive for many people\n• Many individuals might not be able to afford as much as they used to\n• Shoe leather costs may increase as consumers must shop around to find the best deals on food and other products due to the increase in the rate of inflation\n\n0 No rewardable material.\n\nLevel 1 1–2 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n\nLevel 2 3–4 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n\nLevel 3 5–6 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3). Question With reference to the data above and your knowledge of economics, evaluate Number the effectiveness of monetary policy in controlling inflation in a country such as China.", "sources": []}, {"key": "2021-p2-4c", "paper": "2021-p2", "paperLabel": "June 2021 · Paper 2", "q": 4, "id": "4(c)", "marks": 12, "text": "With reference to the data above and your knowledge of economics, evaluate the effectiveness of monetary policy in controlling inflation in a country such as China.", "intro": "Since March 2019 the overall inflation rate for China has been above 2%. In July 2019, China’s food prices increased by 9.1% from the previous year. In particular, meat prices rose by 27% due to the spread of infectious animal diseases. At the same time fresh fruit prices rose by 39.1% as the Chinese fruit supply had been affected by severe weather.\n\nChina’s central bank is called the People’s Bank of China (PBOC). The PBOC has the responsibility of maintaining price stability and promoting growth through the management of monetary policy.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2108", "ms": "AO2 (4 marks)/AO3 (4 marks)/AO4 (4 marks)\n\nAO2 and AO3\n• Monetary policy is the use of interest rates and control of the money supply to manage demand in the economy\n• Monetary policy can be used to reduce inflationary pressures in China by the PBOC increasing interest rates\n• An increase in interest rates tends to reduce spending and investment in the economy thus slowing down economic activity and reducing inflationary pressure\n• There might be a greater reward for saving which may discourage consumers from spending helping to reduce demand in the economy\n• A rise in interest rates may increase the value of the currency which could result in cheaper imports and therefore reduced inflation\n\nAO4\n• However, there can be time lags for the increase in interest rates to filter through the Chinese economy\n• Increasing interest rates may raise the cost of production for firms which may have an even greater negative impact on prices\n• The effectiveness will depend upon the type of inflation China is experiencing which seems to be cost push inflation due to the increases in the price of meat and fresh fruit\n• Demand is not totally dependent on interest rates and there are other factors that have an impact on inflation\n• Monetary policy can therefore conflict with economic growth and employment\n• There are other ways in which the Chinese Government could try and control inflation including supply-side policies\n• These could help to reduce inflationary pressures by helping the Chinese economy to produce more goods and services at all price levels\n\n0 No rewardable material.\n\nLevel 1 1–4 • Demonstrates isolated elements of relevant knowledge and understanding; may lack development of relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Chain of reasoning may be attempted. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n• Only offers one viewpoint, meaning there is an unbalanced and incomplete evaluation, showing limited understanding and awareness. A judgement or conclusion is unlikely to be attempted (AO4).\n\nLevel 2 5–8 • Demonstrates partial selectivity and some accurate knowledge and understanding by developing some relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Chain of reasoning will be present but may be limited. Interpretation of economic information will be good, with some analysis of issues (AO3).\n• Offers more than one viewpoint but the argument may lack balance, leading to an evaluation that may not demonstrate full understanding and awareness. A judgement or conclusion is attempted, but may not be fully supported (AO4).\n\nLevel 3 9–12 • Demonstrates specific and accurate knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Chain of reasoning will be coherent and logical. Interpretation of economic information will be excellent with a thorough analysis of issues (AO3).\n• Offers more than one viewpoint. The argument is well balanced and coherent, leading to an evaluation that demonstrates full understanding and awareness. A supported judgement or conclusion is present (AO4).", "sources": [{"src": "p2-2021-fig5.png", "figs": [5]}]}, {"key": "2022-p2-1b", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 1, "id": "1(b)", "marks": 1, "text": "An increase in which one of the following would be most likely to encourage saving?", "intro": "", "options": [["A", "Interest rate"], ["B", "Income tax rate"], ["C", "Exchange rate"], ["D", "Indirect tax rate"]], "answer": "A", "type": "mcq", "lesson": "IGEN2108", "ms": "AO1 1 mark The only correct answer is:\nA Interest rate\nB is not correct because this would reduce disposable income meaning less saving\nC is not correct because this would make imports cheaper and encourage spending\nD is not correct because this would increase the price of goods meaning less saving (1)\nQuestion What is meant by the term imports? Number Answer", "sources": []}, {"key": "2022-p2-1c", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 1, "id": "1(c)", "marks": 2, "text": "What is meant by the term imports?", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2104", "ms": "AO1 2 marks\nAward 1 mark for reference to goods and 1 mark for reference to being from another country The purchase of goods or services (1) from another country (1)\nAccept any other appropriate response. (2)\nQuestion Describe one reason why governments make benefits payments. Number Answer", "sources": []}, {"key": "2022-p2-1d", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 1, "id": "1(d)", "marks": 2, "text": "Describe one reason why governments make benefit payments.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2106", "ms": "AO1 2 marks\nAward 1 mark for reference to reducing poverty and 1 mark for reference to helping to meet basic needs Reduce poverty/inequality in a country (1) by making benefit payments to assist with meeting basic needs (1)\nAccept any other appropriate response. (2)\nQuestion Using the data in Figure 1, calculate in £bn, the current account for the Number UK year ending July 2019. You are advised to show your working. Mark", "sources": []}, {"key": "2022-p2-1e", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 1, "id": "1(e)", "marks": 2, "text": "Using the data in Figure 1, calculate in £bn, the current account for the UK year ending July 2019. You are advised to show your working.", "intro": "Figure 1 shows the UK’s imports and exports for the year ending July 2019.\n\n(Source: Department for International Trade: UK Trade in Numbers September 2019)", "options": [], "answer": null, "type": "write", "lesson": "IGEN2104", "ms": "A02 2 marks\nAward 1 mark for showing the calculation £646.7bn - £689.9bn (1)\nAward 1 mark for the correct answer = -£43.2bn (1)\nAward 2 marks if the correct answer of -£43.2bn is shown, with pound (£) symbol, even if no calculations are shown\nAward 1 mark if -43.2bn is shown, but with no £ sign, with or without calculations shown (2)\nDo not award marks for formula Question Using the diagram below, draw the effects of the introduction of a Number new quota on the equilibrium price and quantity of haddock. Label the new curve, the new equilibrium price and new equilibrium Mark quantity.", "sources": [{"src": "p2-2022-fig1.png", "figs": [1]}]}, {"key": "2022-p2-1g", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 1, "id": "1(g)", "marks": 3, "text": "Explain one possible reason why a country such as Norway had a current account surplus.", "intro": "Norway had a current account surplus of 19.07bn Norwegian Krone (NOK) in the fourth quarter of 2019.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2104", "ms": "AO2 3 marks\nAward 1 mark for identifying a relevant reason\nAward 1 mark for developing the reason\nAward 1 mark for the response being in context\n• One reason is because of high quality domestic goods (1). High quality goods may increase the demand for exports (1) resulting in more money flowing into the country than flowing out (1)\n• One reason is because of the lower price of domestic goods (1). Lower prices for domestic goods may result in less demand for imported goods (1) resulting in less money flowing out of the country (1)\nAccept any other appropriate response. (3)\nQuestion Analyse how a reduction in indirect taxation is likely to affect the Number standard of living in a country such as the UK. Mark", "sources": []}, {"key": "2022-p2-1h", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 1, "id": "1(h)", "marks": 6, "text": "With reference to the data above and your knowledge of economics, analyse how a reduction in indirect taxation is likely to affect the standard of living in a country such as the UK.", "intro": "The rate of Value Added Tax (VAT), a type of indirect taxation in the UK, is 20%.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2107", "ms": "AO2 (3 marks)/AO3 (3 marks)\n\nAO2 and AO3\n• Indirect taxes are government charges imposed on goods and services\n• Lowering indirect taxes such as VAT will result in consumers paying less for goods and services\n• This allows consumers and firms to make more purchases as prices are cheaper\n• Increased spending could be spent on more/better quality goods and services, thereby increasing the standard of living in the UK for consumers\n• With increased spending within the UK economy, output and employment may increase for firms, further increasing the standard of living (6)\n\n0 No rewardable material.\n\nLevel 1 1–2 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n\nLevel 2 3–4 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n\nLevel 3 5–6 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3). Question Answer Number", "sources": []}, {"key": "2022-p2-2b", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(b)", "marks": 1, "text": "Which one of the following is a possible impact of economic growth?", "intro": "", "options": [["A", "An increase in unemployment"], ["B", "An increase in environmental damage"], ["C", "A reduction in investment"], ["D", "A reduction in tax revenues"]], "answer": "B", "type": "mcq", "lesson": "IGEN2101", "ms": "AO1 1 mark The only correct answer is:\nB An increase in environmental damage\nA is not correct because unemployment should fall due to more jobs being available in the economy\nC is not correct because investment is likely to increase due to economic growth and firms expanding\nD is not correct because tax revenues are likely to rise as more people have jobs/ firms are making more profit (1)\nQuestion State one type of unemployment. Number Answer", "sources": []}, {"key": "2022-p2-2c", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(c)", "marks": 1, "text": "State one type of unemployment.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2103", "ms": "AO1 1 mark\nAward 1 mark for one type.\n• cyclical\n• structural\n• seasonal\n• voluntary\n• frictional\nAccept any other appropriate responses. (1)\nQuestion What is meant by the term recovery? Number Answer", "sources": []}, {"key": "2022-p2-2d", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(d)", "marks": 2, "text": "What is meant by the term recovery?", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGEN2101", "ms": "AO1 2 marks\nAward 1 mark for reference to the economic cycle/recession and\n1 mark for reference to increase in economic activity\nA phase in the economic cycle (1) where GDP starts to rise again/when consumers start to regain confidence/economic activity is on the increase (1)\nAccept any other appropriate response. (2)\nQuestion Explain one impact of rising inflation on shoe leather costs for Nigeria. Number Answer", "sources": []}, {"key": "2022-p2-2e", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 2, "id": "2(e)", "marks": 3, "text": "Explain one impact of rising inflation on shoe leather costs in Nigeria.", "intro": "Nigeria’s rate of inflation increased to 12.2% in February 2020. A rise in the price of food products, such as bread and meat, was the main reason for the increase.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2102", "ms": "AO2 3 marks\nAward 1 mark for identifying a relevant impact\nAward 1 mark for developing the impact\nAward 1 mark for the response being in context\n• One impact is that shoe leather costs may increase (1). Consumers will try to find cheaper bread and meat (1). This means that they will spend more time shopping around and looking for goods (1)\n(3)\nAccept any other appropriate response. Question Draw the effects on the exchange rate of the UK pound (£) from an Number increase in exports to the US. Label the new curve, the new equilibrium exchange rate and the new equilibrium quantity.", "sources": []}, {"key": "2022-p2-3a", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 3, "id": "3(a)", "marks": 1, "text": "Which one of the following is an example of deregulation?", "intro": "", "options": [["A", "Introducing a national minimum wage rate"], ["B", "More health and safety laws"], ["C", "Introducing licences for firms to operate"], ["D", "More firms allowed to enter a market"]], "answer": "D", "type": "mcq", "lesson": "IGEN2109", "ms": "AO1 1 mark The only correct answer is:\nD More firms allowed to enter a market\nA is not correct because this would mean more regulations to implement it\nB is not correct because this increases the amount of regulation\nC is not correct because regulations would be needed to oversee the issuing of licences (1)\nQuestion Answer Number", "sources": []}, {"key": "2022-p2-3b", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 3, "id": "3(b)", "marks": 1, "text": "Which one of the following is likely to cause cost-push inflation?", "intro": "", "options": [["A", "An improvement in productivity"], ["B", "An improvement in weather conditions"], ["C", "An increase in wage rates"], ["D", "An increase in the consumption of goods"]], "answer": "C", "type": "mcq", "lesson": "IGEN2102", "ms": "AO1 1 mark The only correct answer is:\nC An increase in wage rates\nA is not correct because this would lower costs\nB is not correct because this is likely to increase supply of raw materials and therefore reduce cost-push inflation\nD is not correct because this likely to cause demand-pull inflation rather than cost-push inflation (1)\nQuestion Explain one reason why the UK Government gives subsidies to firms Number in the renewable energy market. Mark", "sources": []}, {"key": "2022-p2-3c", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 3, "id": "3(c)", "marks": 3, "text": "Explain one reason why the UK Government gives subsidies to firms in the renewable energy market.", "intro": "The UK Government gives subsidies to firms in the renewable energy market that provide wind and solar energy.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2105", "ms": "AO2 3 marks\nAward 1 mark for identifying a relevant reason\nAward 1 mark for developing the reason\nAward 1 mark for the response being in context\n• One reason is to protect the environment (1). Subsidies encourage firms to provide energy from renewable sources such as solar energy (1) which reduces the pollution from fossil fuels (1)\n• One reason is to lower the cost of renewable energy (1). Subsidies allow renewable energy firms to lower prices (1)\nencouraging consumers to switch to cleaner energy sources (1)\n(3)\nAccept any other appropriate response. Question Analyse the benefits of having a fiscal surplus for a country such as Number Nauru. Mark", "sources": []}, {"key": "2022-p2-3d", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 3, "id": "3(d)", "marks": 6, "text": "With reference to the data above and your knowledge of economics, analyse the benefits of having a fiscal surplus for a country such as Nauru.", "intro": "Nauru is a tiny island country in Micronesia, northeast of Australia. It has a population of 10,824. In 2019, Nauru had a fiscal surplus of 16.1% of GDP.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2107", "ms": "AO2 (3 marks)/AO3 (3 marks)\n\nAO2 and AO3\n• A fiscal surplus is when government tax receipts are greater than government spending\n• In this case, Nauru had a surplus of 16.1% of GDP in 2019\n• The Government of Nauru could use the fiscal surplus in several ways\n• It could use the surplus to reduce taxes for the 10,824 population of the island\n• Alternatively, it could fund new education and training programmes or improve existing public services such as healthcare\n• If the Government of Nauru has any government debts, it has extra funds to repay them\n• This reduces the interest payable on any debt and helps the economy in the future (6)\n\n0 No rewardable material.\n\nLevel 1 1–2 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n\nLevel 2 3–4 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n\nLevel 3 5–6 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3). Question Assess the effectiveness of pollution permits in protecting the Number environment for a country such as the US. Mark", "sources": []}, {"key": "2022-p2-3e", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 3, "id": "3(e)", "marks": 9, "text": "With reference to the data above and your knowledge of economics, assess the effectiveness of pollution permits in protecting the environment for a country such as the US.", "intro": "More than 125 million tonnes of poisonous gases pollute the US state of Colorado’s air every year. US Government records show that 46 million tonnes, or 36% of the total air pollution, comes from 119 large industrial polluters. These include 35 power stations. More than half the electricity in Colorado is still generated from burning coal despite 10 years of government efforts to encourage producers to switch to clean energy.", "options": [], "answer": null, "type": "write", "lesson": "IGEN2105", "ms": "AO2 (3 marks)/AO3 (3 marks)/AO4 (3 marks)\n\nAO2 and AO3\n• Business activity can damage the environment as it has done in the US state of Colorado\n• Pollution permits are a market-based scheme aimed at reducing pollution and trying to encourage firms to reduce the quantity of pollution they create\n• Pollution permits involve giving firms such as power stations a legal right to pollute up to a certain amount\n• If a power station produces less pollution/waste it can sell its pollution permits to other power stations/firms\n• Permits create a financial incentive to pollute less because power stations can then sell their excess permits to other firms\n• It can be a good way to reduce pollution, using the incentives of the market\n\nAO4\n• However, in practice, pollution permits can be difficult to implement and it is difficult to know how many permits to give out to power stations/firms in Colorado\n• If the US Government is too generous in the level of pollution the permit allows, there will be little pollution reduction\n• If the US Government is too strict in the level of pollution the permit allows, power stations/firms may complain it adversely affects output because they cannot comply\n• There may be an incentive to cheat and hide the amount of pollution a firm creates. This could make the scheme ineffective\n• There are alternatives to pollution permits which may be more effective such as fining the power stations on the amount of waste produced\n• A combination of measures may be the most effective way to protect the environment (9)\n\n0 No rewardable material.\n\nLevel 1 1–3 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n• Only offers one viewpoint, meaning there is an unbalanced and incomplete evaluation, showing limited understanding and awareness (AO4).\n\nLevel 2 4–6 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n• Offers more than one viewpoint but the argument may lack balance, leading to an evaluation that may not demonstrate full understanding and awareness (AO4).\n\nLevel 3 7–9 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3).\n• Offers more than one viewpoint. The argument is well balanced and coherent, leading to an evaluation that demonstrates full understanding and awareness (AO4). Question Calculate, to two decimal places, the percentage of spending on all Number existing infrastructure projects that was spent on renewable energy on India in 2019. You are advised to show your working.", "sources": []}, {"key": "2022-p2-4a", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 4, "id": "4(a)", "marks": 2, "text": "Calculate, to two decimal places, the percentage of spending on all existing infrastructure projects that was spent on renewable energy in India in 2019. You are advised to show your working.", "intro": "Figure 4 shows the $618 bn spent by India on existing infrastructure projects in 2019.\n\n(Source: adapted from businessinsider.in)", "options": [], "answer": null, "type": "write", "lesson": "IGEN2109", "ms": "AO2 2 marks\nAward 2 marks for calculating the percentage in spending on renewable energy in 2019 $200bn x 100 (1)\n$618bn = 32.36% (1)\nAward 2 marks if the percentage is accurately calculated as 32.36% even if no calculations are shown\nAward 1 mark if % is missing i.e. 32.36 with or without calculations shown (2)\nNo marks for formula Question Analyse the impact of rising unemployment rates on business Number confidence for a country such as India. Mark", "sources": [{"src": "p2-2022-fig4.png", "figs": [4]}]}, {"key": "2022-p2-4b", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 4, "id": "4(b)", "marks": 6, "text": "With reference to the data above and your knowledge of economics, analyse the impact of rising unemployment rates on business confidence for a country such as India.", "intro": "Figure 5 shows the average unemployment rate (%) in India between 2016 and April 2020.\n\n(Source: adapted from statista.com)", "options": [], "answer": null, "type": "write", "lesson": "IGEN2103", "ms": "AO2 (3 marks)/AO3 (3 marks)\n\nAO2 and AO3\n• Unemployment is when those actively seeking work are unable to find a job\n• Figure 5 shows that unemployment has steadily risen from a low of 3.4% in July 2017 to 23.5% in April 2020\n• This huge increase could reduce business confidence because unemployment is often linked to income and spending\n• As more people are reliant on unemployment benefits for their income, demand for many goods and services will fall which has a negative effect on firms\n• Firms require fewer workers to make goods and services which can increase unemployment further\n• Consumer confidence falls which in turn affects businesses which then become less confident about the future (6)\n\n0 No rewardable material.\n\nLevel 1 1–2 • Demonstrates basic knowledge and understanding by developing relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n\nLevel 2 3–4 • Demonstrates partial knowledge and understanding by developing relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Interpretation of economic information will be good, with some analysis of issues (AO3).\n\nLevel 3 5–6 • Demonstrates clear knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Interpretation of economic information will be excellent, with a thorough analysis of issues (AO3). Question Evaluate the effectiveness of spending on infrastructure to increase Number total output in an economy such as India. Mark", "sources": [{"src": "p2-2022-fig5.png", "figs": [5]}]}, {"key": "2022-p2-4c", "paper": "2022-p2", "paperLabel": "June 2022 · Paper 2", "q": 4, "id": "4(c)", "marks": 12, "text": "With reference to the data above and your knowledge of economics, evaluate the effectiveness of spending on infrastructure to increase total output in a country such as India.", "intro": "The growth of India’s gross domestic product (GDP) slowed to 4.5% in the quarter ending September 2019, the lowest point for 6 years. The fiscal deficit was 3.4% of GDP and was estimated to increase to 3.7% by 2020. This came at a time when the Prime Minister, Narendra Modi, announced plans to spend $1.5 trillion on infrastructure. The expenditure on these projects is expected to be 1.1% of GDP by 2025.\n\n“Building new roads, rail links, airports and other social and economic infrastructure such as smart cities is essential for attracting investments and making India a $5 trillion economy,” said Finance Minister Nirmala Sitharaman.\n\nThis spending on infrastructure will be a huge opportunity for Indian construction, road and cement companies such as GMR Group, Dilip Buildcon and Ultratech.\n\nDomestic steel prices are predicted to increase due to the higher demand from infrastructure projects.\n\nSource adapted from: https://www.bloomberg.com/news/articles/2019-12-31/india-plans-1- 5-trillion-infrastructure-spending-to-spur-growth", "options": [], "answer": null, "type": "write", "lesson": "IGEN2109", "ms": "AO2 (4 marks)/AO3 (4 marks)/AO4 (4 marks)\n\nAO2 and AO3\n• Infrastructure spending is an example of a supply-side policy\n• The productive potential of the Indian economy may increase if the quality of its infrastructure is improved\n• The Indian Government is investing in a wide range of projects including renewable energy, airports, roads and the rail network\n• This may help to increase geographical mobility as well as improve the distribution of goods/services\n• In the short term, building or upgrading transport or energy networks can boost (aggregate) demand through increased construction activity and employment\n• Indian construction, road, cement and steel firms may require additional employees to complete the projects\n• In the long term, infrastructure investment can boost economic growth by attracting investment and increasing the potential supply capacity of an economy\n• The Indian economy slowed to a more than six-year low of 4.5% in 2019 so investing in infrastructure projects could help to boost output without the danger of inflation\n\nAO4\n• However, it can be argued that spending $1.5 trillion may not increase the total output in the Indian economy\n• It is unclear how the Indian Government’s share of the $1.5 trillion will be funded\n• The Indian Government may have to borrow the additional finance adding to its fiscal deficit which is already set to increase to 3.7% in 2020\n• There is an opportunity cost of these investments with no guarantee that total output will increase in the long term\n• These are very ambitious plans and many things can change in a 5-year period which could result in less output for the Indian economy\n• By nature, supply-side policies tend to take a very long time to work and infrastructure investments can be highly complex to manage\n• The overall impact on output will depend upon whether the approved list of projects can add to (aggregate) demand and (aggregate supply)\n• The Indian Government should use a range of supply-side and fiscal policies to increase overall output (12)\n\n0 No rewardable material.\n\nLevel 1 1–4 • Demonstrates isolated elements of relevant knowledge and understanding; may lack development of relevant points. Limited application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will lack selectivity and organisation. Chain of reasoning may be attempted. Interpretation of economic information will be limited, with a lack of analysis of issues (AO3).\n• Only offers one viewpoint, meaning there is an unbalanced and incomplete evaluation, showing limited understanding and awareness. A judgement or conclusion is unlikely to be attempted (AO4).\n\nLevel 2 5–8 • Demonstrates partial selectivity and some accurate knowledge and understanding by developing some relevant points. Partial application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate some selectivity and organisation. Chain of reasoning will be present but may be limited. Interpretation of economic information will be good, with some analysis of issues (AO3).\n• Offers more than one viewpoint but the argument may lack balance, leading to an evaluation that may not demonstrate full understanding and awareness. A judgement or conclusion is attempted, but may not be fully supported (AO4).\n\nLevel 3 9–12 • Demonstrates specific and accurate knowledge and understanding by developing relevant points. Appropriate application of economic terms, concepts, theories and calculations (AO2).\n• Information presented will demonstrate excellent selectivity and organisation. Chain of reasoning will be coherent and logical. Interpretation of economic information will be excellent with a thorough analysis of issues (AO3).\n• Offers more than one viewpoint. The argument is well balanced and coherent, leading to an evaluation that demonstrates full understanding and awareness. A supported judgement or conclusion is present (AO4). ,", "sources": []}]};
